options.customCss:
:root {
	/* Tipografia - Priorizando IBM Plex Sans para o look Carbon */
	--font-family: 'IBM Plex Sans', 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 12px;
	--font-size-label: 14px; /* Tamanho do rótulo "Função" */
	--font-size-input: 14px;
	--font-size-header: 20px;

	/* Cores de Fundo (Preto/Cinza Muito Escuro) */
	--color-background: #161616; /* Gray 100 - Fundo total */
	--color-card-bg: #262626;     /* Gray 90 - Fundo do formulário */
	--color-card-border: #393939; /* Gray 80 - Borda sutil */
	--color-card-shadow: none;    /* Carbon não usa sombras */

	/* Cores de Texto (Claras para Contraste) */
	--color-header: #ffffff;
	--color-label: #e0e0e0;       /* Texto geral das labels */
	--color-input-text: #f4f4f4;  /* Texto dentro do dropdown */
	--color-html-text: #e0e0e0;
	--color-header-subtext: #a8a8a8;
	--color-link: #a8a8a8;

	/* Cores Interativas (O Amarelo Carbon) */
	--color-focus-border: #f1c40f;    /* Amarelo vibrante no foco */
	--color-submit-btn-bg: #f1c40f;   /* Botão de envio amarelo */
	--color-submit-btn-text: #161616; /* Texto preto no botão amarelo */
	--color-required: #f1c40f;        /* Asterisco obrigatório amarelo */
	--color-html-link: #f1c40f;

	/* Cores de Feedback (Mantendo o padrão de erro) */
	--color-error: #ea1f30;

	/* Nota de Teste (Amarelo sobre Fundo Escuro) */
	--color-test-notice-text: #f1c40f;
	--color-test-notice-bg: #262626;
	--color-test-notice-border: #f1c40f;

	/* Arredondamentos (Tudo Quadrado - 0px) */
	--border-radius-card: 0px;
	--border-radius-input: 0px;
	--border-radius-clear-btn: 0px;

	/* Dimensões e Espaçamento */
	--container-width: 480px; /* Um pouco mais largo para o visual técnico */
	--padding-card: 32px;
	--submit-btn-height: 48px;

	/* Overrides */
	--box-shadow-card: none;
}

/* --- Ajustes específicos para o seu Dropdown de "Função" --- */

/* 1. Garante que o rótulo "Função" use o amarelo interativo */
label[for="funcao"], 
label:has(+ select[name="funcao"]),
.n8n-form-label:contains("Função") {
    color: var(--color-focus-border) !important;
    font-weight: var(--font-weight-bold);
    text-transform: uppercase; /* Opcional: look mais terminal */
    letter-spacing: 1px;
}

/* 2. Estilização do campo select (dropdown) */
select {
    background-color: #393939 !important; /* Gray 80 */
    border: 1px solid #525252 !important;  /* Gray 70 */
    color: var(--color-input-text) !important;
    appearance: none; /* Remove seta padrão */
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="%23f4f4f4" d="M8 11L3 6h10z"/></svg>') !important;
    background-repeat: no-repeat !important;
    background-position: right 12px center !important;
}

/* 3. Estilo de Foco (Borda Amarela) */
select:focus, input:focus, textarea:focus {
    outline: 2px solid var(--color-focus-border) !important;
    outline-offset: -1px;
    border-color: transparent !important;
}

/* N8N FORM CUSTOM CSS - CARBON DESIGN SYSTEM (YELLOW ACCENT)
*/

:root {
	/* Tipografia */
	--font-family: 'IBM Plex Sans', 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 12px;
	--font-size-label: 14px;
	--font-size-input: 14px;
	--font-size-header: 20px;

	/* Cores de Fundo (Carbon Gray 100 & 90) */
	--color-background: #161616; 
	--color-card-bg: #262626;     
	--color-card-border: #393939; 

	/* Cores de Texto */
	--color-header: #ffffff;
	--color-label: #e0e0e0;       
	--color-input-text: #f4f4f4;  
	--color-html-text: #e0e0e0;
	--color-header-subtext: #a8a8a8;

	/* Cores Interativas (Amarelo Carbon) */
	--color-focus-border: #f1c40f;    
	--color-submit-btn-bg: #f1c40f;   
	--color-submit-btn-text: #161616; 
	--color-required: #f1c40f;        

	/* Feedback */
	--color-error: #ea1f30;

	/* Arredondamentos (Zero/Square) */
	--border-radius-card: 0px;
	--border-radius-input: 0px;
	--border-radius-clear-btn: 0px;

	/* Dimensões */
	--container-width: 480px;
	--padding-card: 32px;
	--submit-btn-height: 48px;
	--box-shadow-card: none;
}

/* --- Global & Container --- */
body {
    background-color: var(--color-background) !important;
    font-family: var(--font-family) !important;
}

.n8n-form-card {
    background-color: var(--color-card-bg) !important;
    border: 1px solid var(--color-card-border) !important;
    border-radius: var(--border-radius-card) !important;
    padding: var(--padding-card) !important;
    box-shadow: none !important;
}

/* --- Títulos e Textos --- */
h1, h2 {
    color: var(--color-header) !important;
    font-weight: var(--font-weight-bold) !important;
}

/* --- Labels Gerais --- */
label {
    color: var(--color-label);
    font-size: var(--font-size-label);
    margin-bottom: 8px !important;
    display: block;
}

/* --- DESTAQUE: Labels de "Função" e "BM" --- */
label[for*="funcao"], 
label[for*="bm"],
label:has(+ select),
label:has(+ input) {
    color: var(--color-focus-border) !important; /* Amarelo */
    font-weight: var(--font-weight-bold) !important;
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* --- Inputs e Selects (Campos de Preenchimento) --- */
input[type="text"], 
input[type="email"], 
input[type="number"], 
textarea, 
select {
    background-color: #393939 !important; /* Gray 80 */
    border: 1px solid #525252 !important;  /* Gray 70 */
    border-radius: 0px !important;
    color: var(--color-input-text) !important;
    padding: 12px !important;
    font-size: var(--font-size-input) !important;
    transition: all 0.2s ease;
    width: 100%;
}

/* Estilo específico para o Dropdown (seta customizada) */
select {
    appearance: none !important;
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="%23f4f4f4" d="M8 11L3 6h10z"/></svg>') !important;
    background-repeat: no-repeat !important;
    background-position: right 12px center !important;
}

/* --- Foco (Estado Ativo) --- */
input:focus, select:focus, textarea:focus {
    outline: 2px solid var(--color-focus-border) !important;
    outline-offset: -1px;
    border-color: transparent !important;
    background-color: #454545 !important;
}

/* --- Botão de Envio --- */
button[type="submit"] {
    background-color: var(--color-submit-btn-bg) !important;
    color: var(--color-submit-btn-text) !important;
    font-weight: var(--font-weight-bold) !important;
    height: var(--submit-btn-height) !important;
    border: none !important;
    border-radius: 0px !important;
    text-transform: uppercase;
    letter-spacing: 1px;
    cursor: pointer;
    transition: opacity 0.2s;
}

button[type="submit"]:hover {
    opacity: 0.9;
}

/* --- Ajuste de Resalva (Asterisco de Obrigatório) --- */
.n8n-form-required-star {
    color: var(--color-required) !important;
}

parameters.jsCode:
// Puxa as BMs do nó "Get bm"
const bms = $('Get bm').all().map(item => item.json);

// Puxa o status atual que está chegando na entrada deste nó
const currentStatus = $input.all()[0].json;

// Passa os dados limpos para frente
return [{
  json: {
    bms: bms,
    currentStatus: currentStatus
  }
}];

